For $p>0$, the space of \textit{mixed differential $p$-forms} is the $p$th bigraded symmetric power
    \begin{align*}
        \tilde{\Omega}^p(A)=\mathrm{Sym}^p_{\tilde{\Omega}^0(A)}(\tilde{\Omega}^1(A)).
    \end{align*}
The \textit{total space of mixed differential forms} is
    \begin{align*}
        \tilde{\Omega}^\bullet(A):=\bigoplus_{p\ge 0}\tilde{\Omega}^p(A)
        =\mathrm{Sym}\{z_1,\cdots,z_m,\partial_{m+1},\cdots,\partial_l,dz_1,
        \cdots,dz_m,z_{m+1}^*,\cdots,z_l^*\}.
    \end{align*}

\cite{CY}\label{mixedcartan}
Let $\Sigma$ be a bigraded space and let $A = \mathcal{O}(\Sigma)$ be defined as above. For any homogeneous mixed polyvector fields $P$ and $Q$, the following identity holds:
\begin{align}\label{mixedcartanformula}
    [[\tilde{\iota}_P,\tilde{d}],\tilde{\iota}_Q] = \tilde{\iota}_{[P,Q]}.
\end{align}

\label{prop2.14}
Let $A=\mathcal O(\Sigma)$ have a Poisson bivector $\pi$ of degree $(0,-2)$ and a mixed volume form $\gamma$, which is $\tilde d$-closed by Proposition~\ref{prop:canonical-volume}. Then every homogeneous polyvector $P$ satisfies
\begin{align}\label{twistedpartial}
(-1)^{w(P)}\tilde{\iota}_{\delta^\pi(P)}\gamma
=
\partial_\pi(\tilde{\iota}_P\gamma)
-
\tilde{\iota}_\upsilon(\tilde{\iota}_P\gamma),
\end{align}
where $\upsilon$ denotes the modular vector field associated with $\gamma$.

\label{horiso}
Contraction with $\gamma$ induces an isomorphism
\begin{equation}\label{twistedpoincare}
\mathrm{HP}^{\bullet,\bullet}(A)
\cong
\widetilde{\mathrm{HP}}_{u-\bullet,v-\bullet}
(A;\upsilon).
\end{equation}

\label{diff calculus}
A differential calculus $(\mathrm{H}^{\bullet,\bullet},
\mathrm{H}_{\bullet,\bullet}, \cup, \iota, [-,-], d)$ is
called a \textit{differential calculus with duality} if 
there exist integers $u,v$ and an element $\gamma\in \mathrm{H}_{u,v}$
such that
\begin{enumerate}
\item[(1)]  For the unit $1\in\mathrm H^{0,0}$, we have $\iota_1\gamma=\gamma$ and $d(\gamma)=0$;
\item[(2)]  for any $i,j\in \mathbb Z$,
\begin{equation*}\label{PD}
\mathrm{PD}(-):=\iota_{(-)}\gamma : \mathrm{H}^{i,j}
\to \mathrm{H}_{u-i,v-j}
\end{equation*}
is an isomorphism.
\end{enumerate}
We call the isomorphism $\mathrm{PD}$ the
\textit{Van den Bergh duality} (or
\textit{noncommutative Poincar\'e duality}) between
$\mathrm{H}^{\bullet,\bullet}$ and
$\mathrm{H}_{\bullet,\bullet}$.

A {\it Batalin--Vilkovisky
algebra} is a bigraded commutative algebra $A$ equipped with a linear operator $\Delta: A^{i,j}\to A^{i,j-1}$ of degree $(0,-1)$, such that
\begin{enumerate}
\item[$(1)$] $\Delta$ is 
a differential, i.e., $\Delta^2=0$; 
\item[$(2)$] $\Delta$ is a second-order operator; that is,
\begin{align*}
\Delta(a  b c)
=& \Delta(a b)c+(-1)^{|a||\Delta|}a 
\Delta(b  c)+(-1)^{|b|(|a|+|\Delta|)}b  
\Delta(a   c)\nonumber \\
&- (\Delta a)  b   c-(-1)^{|a||\Delta|}a 
(\Delta b) c-(-1)^{|\Delta|(|a|+|b|)}a  b(\Delta c).
\end{align*}
\end{enumerate}

\label{prop:diagonal-koszul}
A Poisson structure on $\mathcal{O}(k^{m||n})$
is diagonal with respect to $x_1,\ldots,x_m$, $y_1,\ldots,y_n$
if and only if it has the form
\begin{equation}\label{eq:diagonal-original}
\begin{aligned}
\pi=
\sum_{1\leq i<j\leq m}
a_{ij}x_i x_j\,
\partial_{x_i}\wedge\partial_{x_j}
+
\sum_{1\leq s<t\leq n}
b_{st}y_s y_t\,
\partial_{y_s}\wedge\partial_{y_t}
+
\sum_{i=1}^{m}\sum_{s=1}^{n}
c_{is}x_i y_s\,
\partial_{x_i}\wedge\partial_{y_s},
\end{aligned}
\end{equation}
where $a_{ij},b_{st},c_{is}\in k$.
Under \eqref{corres}, its Koszul dual is
\begin{equation}\label{eq:diagonal-dual}
\begin{aligned}
\pi^!=
\sum_{1\leq i<j\leq m}
a_{ij}\xi_i\xi_j\,
\partial_{\xi_i}\wedge\partial_{\xi_j}
+
\sum_{1\leq s<t\leq n}
b_{st}\eta_s\eta_t\,
\partial_{\eta_s}\wedge\partial_{\eta_t}
-
\sum_{i=1}^{m}\sum_{s=1}^{n}
c_{is}\xi_i\eta_s\,
\partial_{\xi_i}\wedge\partial_{\eta_s}.
\end{aligned}
\end{equation}
In particular, $\pi^!$ is diagonal with respect to
$\xi_1,\ldots,\xi_m,\eta_1,\ldots,\eta_n$.
Every choice of $a_{ij},b_{st},c_{is}\in k$ gives a Poisson structure. Conversely, every Poisson structure diagonal in the specified dual coordinates is obtained in this way.

For the coefficient expressions \eqref{pi1} and
\eqref{pi2}, the modular vector fields are given by
$$
\begin{aligned}
\upsilon
={}&
\sum_{i_1,i_2,j_2}
(-1)^{1+\epsilon_{i_1}
+\epsilon_{i_1}\epsilon_{i_2}}
C^{i_1,i_2}_{i_1,j_2}\,
z_{i_2}\partial_{z_{j_2}}
+
\sum_{i_1,i_2,j_1}
(-1)^{\epsilon_{i_1}}
C^{i_1,i_2}_{j_1,i_1}\,
z_{i_2}\partial_{z_{j_1}}
\\
&+
\sum_{i_1,i_2,j_2}
(-1)^{1+\epsilon_{i_2}}
C^{i_1,i_2}_{i_2,j_2}\,
z_{i_1}\partial_{z_{j_2}}
+
\sum_{i_1,i_2,j_1}
(-1)^{\epsilon_{i_2}
+\epsilon_{i_1}\epsilon_{i_2}}
C^{i_1,i_2}_{j_1,i_2}\,
z_{i_1}\partial_{z_{j_1}},
\end{aligned}
$$
and
$$
\begin{aligned}
\upsilon^!
={}&
\sum_{i_1,i_2,j_2}
(-1)^{1+\epsilon_{i_1}+\epsilon_{i_2}
+\epsilon_{i_1}\epsilon_{i_2}}
C^{i_1,j_2}_{i_1,i_2}\,
\zeta_{i_2}\partial_{\zeta_{j_2}}
+
\sum_{i_1,i_2,j_1}
(-1)^{1+\epsilon_{i_1}+\epsilon_{i_2}}
C^{j_1,i_1}_{i_1,i_2}\,
\zeta_{i_2}\partial_{\zeta_{j_1}}
\\
&+
\sum_{i_1,i_2,j_2}
(-1)^{\epsilon_{i_1}+\epsilon_{i_2}}
C^{i_2,j_2}_{i_1,i_2}\,
\zeta_{i_1}\partial_{\zeta_{j_2}}
+
\sum_{i_1,i_2,j_1}
(-1)^{\epsilon_{i_1}+\epsilon_{i_2}
+\epsilon_{i_1}\epsilon_{i_2}}
C^{j_1,i_2}_{i_1,i_2}\,
\zeta_{i_1}\partial_{\zeta_{j_1}}.
\end{aligned}
$$
Here all indices range from $1$ to $m+n$.
The signs in the correspondence are determined by
$$
\Psi(z_i\partial_{z_j})
=
\partial_{\zeta_i}\zeta_j
=
(-1)^{\epsilon_i\epsilon_j}
\zeta_j\partial_{\zeta_i}.
$$

\label{comdiagram}
    Let $A=(\mathcal{O}(k^{m||n}),\pi)$ be a quadratic Poisson algebra with $|\pi|=(0,-2)$, and let $A^!=(\mathcal{O}(k^{n\wedge m}),\pi^!)$ be its Koszul dual Poisson algebra.
    Their modular vector fields are denoted by $\upsilon$ and $\upsilon^!$, respectively.
    Then the following diagram commutes:
\begin{equation}\label{diagPoisson}
\xymatrixcolsep{4pc}
\xymatrix{
\mathrm{HP}^{\bullet,\bullet}(A)
\ar[r]^-{\cong}
\ar[d]_{\cong}
&
\widetilde{\mathrm{HP}}_{-n-\bullet,m-\bullet}
(A;\upsilon)
\ar[d]_{\cong}
\\
\mathrm{HP}^{\bullet,\bullet}(A^!)
\ar[r]^-{\cong}
&
\widetilde{\mathrm{HP}}_{-n-\bullet,m-\bullet}
(A^!;\upsilon^!).
}
\end{equation}
